cat > /home/sfmqrb/git/rishe/data/verification/page-150.json <<'JSONEOF'
{
 "pdf_page": 150,
 "book_page": 120,
 "verified_by": "claude-opus-5",
 "verified_on": "2026-09-05",
 "entries": [
  {
   "entry": 0,
   "root": "Eis 2",
   "verdict": "confirmed",
